    return { ok: false, status: 0, latencyMs, error: err instanceof Error ? err.message : String(err) };
  } finally {
    clearTimeout(timeout);
  }
}

function percentile(sorted: number[], p: number): number {
  if (sorted.length === 0) return 0;
  const idx = Math.min(sorted.length - 1, Math.floor((p / 100) * sorted.length));
  return sorted[idx];
}

export async function runStressTest(): Promise<StressResult> {
  const startedAt = new Date().toISOString();
  const startMs = Date.now();
  const latenciesMs: number[] = [];
  const statusCodes: Record<number, number> = {};
  const errors: string[] = [];
  let successCount = 0;
  let failureCount = 0;

  // Bounded concurrency: fire TOTAL_REQUESTS in batches of CONCURRENCY.
  for (let i = 0; i < TOTAL_REQUESTS; i += CONCURRENCY) {
    const batch = Math.min(CONCURRENCY, TOTAL_REQUESTS - i);
    const promises = Array.from({ length: batch }, () => singleRequest());
    const results = await Promise.all(promises);
    for (const r of results) {
      latenciesMs.push(r.latencyMs);
      statusCodes[r.status] = (statusCodes[r.status] || 0) + 1;
      if (r.ok) {
        successCount++;
      } else {
        failureCount++;
        if (r.error) errors.push(r.error.slice(0, 200));
      }
    }
  }

  latenciesMs.sort((a, b) => a - b);
  const durationMs = Date.now() - startMs;
  const completedAt = new Date().toISOString();
  const result: StressResult = {
    targetUrl: TARGET_URL,
    totalRequests: TOTAL_REQUESTS,
    concurrency: CONCURRENCY,
    startedAt,
    completedAt,
    durationMs,
    successCount,
    failureCount,
    successRate: successCount / TOTAL_REQUESTS,
    statusCodes,
    latenciesMs,
    p50Ms: percentile(latenciesMs, 50),
    p90Ms: percentile(latenciesMs, 90),
    p99Ms: percentile(latenciesMs, 99),
    minMs: latenciesMs[0] || 0,
    maxMs: latenciesMs[latenciesMs.length - 1] || 0,
    avgMs: latenciesMs.length > 0 ? Math.round(latenciesMs.reduce((a, b) => a + b, 0) / latenciesMs.length) : 0,
    errors: errors.slice(0, 10),
  };

  // Write results to a JSON file for audit/proof.
  try {
    const { writeFile: wf, mkdir: mkd } = await import('node:fs/promises');
    const { dirname: dn } = await import('node:path');
    await mkd(dn(RESULTS_FILE), { recursive: true });
    await wf(RESULTS_FILE, JSON.stringify(result, null, 2) + '\n', 'utf8');
  } catch (err) {
    // Non-fatal — results are still returned.
    errors.push(\`Failed to write results file: ${err instanceof Error ? err.message : String(err)}\`);
  }
  return result;
}

// Auto-run when executed directly (bun run stress-<id>.ts).
if (import.meta.url === \`file:\${process.argv[1]}\`) {
  runStressTest().then((r) => {
    console.log(JSON.stringify(r, null, 2));
    process.exit(r.successRate >= 0.95 ? 0 : 1);
  }).catch((e) => {
    console.error('Stress test failed:', e);
    process.exit(2);
  });
}
`;

