    body: JSON.stringify({ message, requestId, context: { source: 'e2e_partial_completion' } })
  });
  const text = await res.text();
  let parsed; try { parsed = JSON.parse(text); } catch { parsed = { raw: text.slice(0, 400) }; }
  const answer = parsed.answer || '';
  // Extract task id from the answer (format: ivx-worker-<uuid>)
  const jobIdMatch = answer.match(/ivx-worker-[0-9a-f-]{36}/);
  return { source: parsed.source, answer: answer.slice(0, 800), jobId: jobIdMatch ? jobIdMatch[0] : null };
}

async function pollJob(jobId, label) {
  for (let i = 1; i <= 40; i++) {
    const res = await fetch(`https://api.ivxholding.com/api/ivx/senior-developer/worker/jobs/${jobId}`, {
      headers: { 'Authorization': `Bearer ${AT}` }
    });
    const text = await res.text();
    let d; try { d = JSON.parse(text); } catch { console.log(`[${label}] poll ${i}: bad json`); await new Promise(r => setTimeout(r, 4000)); continue; }
    const j = d.job || {};
    const stage = j.stage, progress = j.progressPercent, detail = j.stageDetail, error = j.error;
    console.log(`[${label}] poll ${i}: stage=${stage} progress=${progress} detail=${detail ? detail.slice(0, 60) : ''} error=${error ? error.slice(0, 80) : ''}`);
    const terminal = ['COMPLETED', 'VERIFIED', 'FAILED', 'BLOCKED', 'CANCELLED'];
    if (terminal.includes(stage)) {
      const r = j.result;
      const summary = {
        stage, progress, error,
        ok: r && r.ok,
        changedFiles: r && r.changedFiles,
        patchStatus: r && r.patchProposal && r.patchProposal.status,
        patchOps: r && r.patchProposal && r.patchProposal.operations && r.patchProposal.operations.map(o => ({ path: o.path, kind: o.kind })),
        gitStatus: r && r.gitDeployOperator && r.gitDeployOperator.status,
        gitCommitSha: r && r.gitDeployOperator && r.gitDeployOperator.github && r.gitDeployOperator.github.commitSha,
        gitCommittedPaths: r && r.gitDeployOperator && r.gitDeployOperator.github && r.gitDeployOperator.github.committedPaths,
      };
      console.log(`[${label}] FINAL:`, JSON.stringify(summary, null, 2));
      return summary;
    }
    await new Promise(r => setTimeout(r, 4000));
  }
  console.log(`[${label}] poll timed out`);
  return null;
}

